import * as THREE from './three.module.js';let grain;
export function racketWoodMaterials(){if(!grain){const width=512,height=128,data=new Uint8Array(width*height*4);let seed=31;const rand=()=>{seed=(1664525*seed+1013904223)>>>0;return seed/4294967296;};for(let y=0;y<height;y++)for(let x=0;x<width;x++){const fiber=Math.sin(y*.63+Math.sin(x*.016)*.45)*.055+Math.sin(y*2.4+x*.003)*.025+(rand()-.5)*.035,streak=Math.sin(y*.29+Math.sin(x*.009)*.3)> .94?-.10:0,k=1+fiber+streak,index=(y*width+x)*4;data[index]=Math.min(255,196*k);data[index+1]=Math.min(255,161*k);data[index+2]=Math.min(255,114*k);data[index+3]=255;}if(typeof document!=='undefined'){const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const context=canvas.getContext('2d'),pixels=context.createImageData(width,height);pixels.data.set(data);context.putImageData(pixels,0,0);grain=new THREE.CanvasTexture(canvas);}else grain=new THREE.DataTexture(data,width,height);grain.colorSpace=THREE.SRGBColorSpace;grain.wrapS=grain.wrapT=THREE.RepeatWrapping;grain.needsUpdate=true;}
const rim=new THREE.MeshStandardMaterial({color:'#d9b783',map:grain,bumpMap:grain,bumpScale:.0015,roughness:.72});const shaftMap=grain.clone();shaftMap.center.set(.5,.5);shaftMap.rotation=Math.PI/2;shaftMap.needsUpdate=true;return {rim,shaft:new THREE.MeshStandardMaterial({color:'#d3ab76',map:shaftMap,bumpMap:shaftMap,bumpScale:.0015,roughness:.76})};}
